 /** Every switched-on playlist by name, for the main screen's status line (all are in use; none is "the" playlist). */
 String playlistsLine(){JSONArray on=library.inUse();StringBuilder b=new StringBuilder();for(int i=0;i<on.length();i++){JSONObject p=on.optJSONObject(i);if(p==null)continue;if(b.length()>0)b.append(", ");b.append(Library.nameOf(p));}return on.length()==1?"Playlist: "+b:"Playlists: "+b;}
