  TextView tile=label(icon+"\n"+title,24);tile.setGravity(Gravity.CENTER);tile.setTypeface(null,Typeface.BOLD);tile.setFocusable(true);tile.setClickable(true);tile.setBackground(homeTileBackground(false));
