 void playlists(){if(Brand.OTA)settings();else Menus.playlists(this);}
 void settings(){Menus.settings(this);}
 void recent(){Menus.recent(this);}
 /** Back or Cancel from an add/edit form. */
 void leaveForm(){if(library.isEmpty())setup();else playlists();}
 /** Makes a saved playlist the one every screen shows, dropping lists loaded for the old one. */
 /** Movies or Series: while an M3U (no movies) is the active playlist, switch to the first playlist that has them. */
 void browseVod(String m){if(library.activeIsM3u()){JSONObject p=library.firstVod();if(p!=null)switchPlaylist(p);}browse(m);}
 void switchPlaylist(JSONObject p){Antenna.remember(this,p);library.activate(p);forgetPlaylistData();}
 void forgetPlaylistData(){MiniGuide.clear();items=new JSONArray();categories=new JSONArray();category="";liveIndex=null;liveIndexAccount="";searchQuery="";zapList=null;tvGuide=null;}
 /** The screen chosen in Settings → Open at start-up. */
 void start(){/* An update due on start-up may show its progress screen first (Settings > Manage playlists). */if(!AutoRefresh.atStart(this,this::startScreen))startScreen();}
 /** The screen chosen in Settings as the first screen (without replaying the last channel): used after adding a playlist or restoring, instead of always Home. */
 void firstScreen(){String s=prefs.getString("start_screen","home");if(liveOnly()||s.equals("last")||s.equals("home")){home();return;}startScreen();}
 void startScreen(){String s=prefs.getString("start_screen","home");if(liveOnly()){if(!s.equals("last")||!playLast())home();return;}if(s.equals("live"))browse("live");else if(s.equals("guide")){home();openGuide(null);}else if(s.equals("favorites"))favorites();else if(s.equals("recent"))recent();else if(s.equals("last")){home();playLast();}else home();}
 /**
  * Start-up "Last channel watched": plays the last live channel. CH+/CH- go through your Favorites first (the
  * channel is added to the front if it isn't one); with no favorites they go through all channels. False if nothing was watched yet.
  */
 boolean playLast(){JSONArray r=library.recent();for(int i=0;i<r.length();i++){JSONObject o=r.optJSONObject(i);if(o==null||!o.optString("type").equals("live"))continue;String id=o.optString("id");JSONArray fav=new JSONArray(),all=favoriteLiveAll();String pid=library.activeId();boolean has=false;for(int k=0;k<all.length();k++){JSONObject f=all.optJSONObject(k);if(f!=null&&f.optString("playlist").equals(pid)){fav.put(f);has|=id.equals(f.optString("stream_id"));}}if(fav.length()>0&&!has){JSONArray withLast=new JSONArray();try{withLast.put(new JSONObject().put("stream_id",id).put("name",o.optString("title")).put("container_extension",o.optString("ext","ts")).put("playlist",pid));}catch(JSONException ignored){}for(int k=0;k<fav.length();k++)withLast.put(fav.opt(k));fav=withLast;}if(!mode.equals("home"))mode="home";zapList=fav.length()>0?fav:null;play("live",id,o.optString("ext","ts"),o.optString("title"));return true;}return false;}
 int hiddenCount(){int n=hiddenChannels().size();for(String sec:new String[]{"live","vod","series"})n+=prefs.getStringSet(hiddenKey(sec),new HashSet<>()).size();return n;}
 void unhideAll(){android.content.SharedPreferences.Editor e=prefs.edit().remove(hiddenChannelsKey());for(String sec:new String[]{"live","vod","series"})e.remove(hiddenKey(sec));e.apply();}
 EditText field(LinearLayout parent,String hint,String val){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(val);e.setTextColor(-1);e.setHintTextColor(Theme.HINT);e.setPadding(dp(16),0,dp(16),0);e.setBackground(bg(PANEL));e.setOnFocusChangeListener((v,f)->e.setBackground(bg(f?Theme.FOCUS:PANEL)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(57));lp.setMargins(dp(5),dp(5),dp(5),dp(5));parent.addView(e,lp);return e;}
 String base(){return saved("host")+"/player_api.php?username="+enc(saved("user"))+"&password="+enc(saved("pass"));}String enc(String s){return XtreamProtocol.encode(s);}

 interface Done{void run(JSONObject obj);} void request(String action,Done cb,String error){if(saved("host").isEmpty()){new Dialogs.Builder(this).setMessage("Add a playlist first").setPositiveButton("Login",(d,w)->login()).setNegativeButton("Cancel",null).show();return;}if(action.equals("player_api.php")){fetch(base(),cb,error);return;}final int generation=screenGeneration;new Thread(()->{try{JSONObject obj=apiBlocking(action);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)cb.run(obj);});}catch(OutOfMemoryError e){System.gc();runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)new Dialogs.Builder(this).setMessage("This list is too big for this device's memory. Pick a category instead of All categories.").setPositiveButton("OK",null).show();});}catch(Throwable e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)new Dialogs.Builder(this).setMessage(error+(library.activeIsM3u()?". Check the playlist link and network, or refresh it from Playlists.":". Check the server address, account and network, then retry.")).setPositiveButton("OK",null).show();});}}).start();}
 /**
  * One player_api action for the active playlist. M3U playlists are answered locally; a custom XMLTV guide
  * answers get_short_epg. Blocking: call off the UI thread.
  */
 JSONObject apiBlocking(String action) throws Exception{return library.shortEpgWithExtras(action,null,()->providerApi(action));}
 /** The playlist's own answer, before supplemental guides are mixed in. */
 JSONObject providerApi(String action) throws Exception{if(library.activeIsM3u())return library.answer(action);if(action.startsWith("get_short_epg")&&!saved("epg_url").isEmpty()){String sid=null;int lim=4;for(String part:action.split("&")){if(part.startsWith("stream_id="))sid=java.net.URLDecoder.decode(part.substring(10),"UTF-8");else if(part.startsWith("limit="))try{lim=Integer.parseInt(part.substring(6));}catch(NumberFormatException ignored){}}if(sid!=null){JSONArray e=library.shortEpg(sid,lim);if(e!=null)return new JSONObject().put("epg_listings",e);}}/* Channel, movie and series lists can be huge: read them item by item instead of as one big text (live channels keep only the fields the app uses). */if(action.startsWith("get_live_streams"))return new JSONObject().put("list",Library.downloadList(base()+"&action="+action,60000,Library.LIVE_FIELDS));if(action.startsWith("get_vod_streams")||action.equals("get_series")||action.startsWith("get_series&"))return new JSONObject().put("list",Library.downloadList(base()+"&action="+action,90000,null));String text=Library.download(base()+"&action="+action,30000);return text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);}
 /** Background player_api call with no error dialog: cb gets null on failure. */
 void apiQuiet(String action,Done cb){new Thread(()->{JSONObject obj=null;try{obj=apiBlocking(action);}catch(Throwable ignored){}final JSONObject result=obj;runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())cb.run(result);});}).start();}
 void fetch(String url,Done cb,String error){final int generation=screenGeneration;new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(16000);try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);String text=out.toString("UTF-8");JSONObject obj=text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)cb.run(obj);});}finally{c.disconnect();}}catch(Throwable e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)new Dialogs.Builder(this).setMessage(error+". Check the server address, account and network, then retry.").setPositiveButton("OK",null).show();});}}).start();}
 /** Background request with no error dialog and no screen check: cb gets null on failure. */
