 boolean toggleMyListIn(String pre,String type,JSONObject item){String key=type.equals("series")?"series_id":"stream_id",id=item.optString(key);JSONArray old;try{old=new JSONArray(prefs.getString(pre+"mylist_"+type,"[]"));}catch(JSONException e){old=new JSONArray();}JSONArray out=new JSONArray();boolean removed=false;for(int i=0;i<old.length();i++){JSONObject o=old.optJSONObject(i);if(o==null)continue;if(id.equals(o.optString(key))){removed=true;continue;}out.put(o);}if(!removed){JSONArray withNew=new JSONArray();try{JSONObject keep=new JSONObject();for(String k:new String[]{key,"name","container_extension","stream_icon","cover","category_id","rating","year"})if(item.has(k))keep.put(k,item.opt(k));withNew.put(keep);}catch(JSONException ignored){}for(int i=0;i<out.length();i++)withNew.put(out.opt(i));out=withNew;}prefs.edit().putString(pre+"mylist_"+type,out.toString()).apply();return !removed;}
