 /** Live channels without hidden ones, in the Settings > Appearance > Channel order. */
 JSONArray withoutHiddenChannels(JSONArray all){Set<String> hidden=hiddenChannels();if(hidden.isEmpty())return ChannelOrder.apply(prefs,all);JSONArray kept=new JSONArray();for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null&&hidden.contains(item.optString("stream_id")))continue;kept.put(all.opt(i));}return ChannelOrder.apply(prefs,kept);}
