 /** Favorites from every saved playlist, the active one first. Picking one from another playlist switches to it first. */
 void favorites(){mode="favorites";shell("FAVORITES");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView favoritesScroll=new ScrollView(this);favoritesScroll.addView(list);body.addView(favoritesScroll,new LinearLayout.LayoutParams(-1,-1));button("← Live TV",list,()->browse("live"));
  List<JSONObject> lists=new ArrayList<>();JSONArray all=library.inUse();String activeId=library.activeId();Set<String> seen=new HashSet<>();
  for(int pass=0;pass<2;pass++)for(int i=0;i<all.length();i++){JSONObject p=all.optJSONObject(i);if(p==null||(pass==0)!=p.optString("id").equals(activeId))continue;if(seen.add(Library.prefixOf(p)))lists.add(p);}
  Map<String,?> stored=prefs.getAll();List<Object[]> groups=new ArrayList<>();
  for(JSONObject p:lists){String pre=Library.prefixOf(p);List<String[]> favs=new ArrayList<>();for(Map.Entry<String,?> e:stored.entrySet()){String k=e.getKey(),title=String.valueOf(e.getValue());if(!k.startsWith(pre+"fav_")||title.isEmpty())continue;String[] parts=k.substring(pre.length()).split("_",3);if(parts.length!=3||!parts[1].equals("live"))continue;String ext=stored.get(pre+"ext_"+parts[1]+"_"+parts[2])==null?"":String.valueOf(stored.get(pre+"ext_"+parts[1]+"_"+parts[2]));favs.add(new String[]{parts[1],parts[2],title,ext,k});}
   if(favs.isEmpty())continue;Collections.sort(favs,(x,y)->{int t=favOrder(x[0])-favOrder(y[0]);return t!=0?t:x[2].compareToIgnoreCase(y[2]);});groups.add(new Object[]{p,favs});}
  if(groups.isEmpty()){TextView none=label("No favorites yet. Hold OK on a channel and choose Add Favorite. Movies and series go in My List.",18);none.setPadding(dp(12),dp(16),dp(12),dp(8));list.addView(none);}
  boolean headers=groups.size()>1||(groups.size()==1&&!((JSONObject)groups.get(0)[0]).optString("id").equals(activeId));
  for(Object[] g:groups){JSONObject p=(JSONObject)g[0];@SuppressWarnings("unchecked") List<String[]> favs=(List<String[]>)g[1];String pre=Library.prefixOf(p);boolean here=p.optString("id").equals(activeId);
   if(headers){String name=p.optString("title");if(name.isEmpty())name=Menus.hostOf(p.optString(Library.M3U.equals(p.optString("type"))?"url":"host"));TextView h=label("☰  "+name+(here?"   (current playlist)":""),17);h.setTextColor(Theme.HEADER);h.setPadding(dp(12),dp(14),dp(12),dp(4));list.addView(h);}
   JSONArray favLive=new JSONArray();for(String[] f:favs)if(f[0].equals("live")){try{favLive.put(new JSONObject().put("stream_id",f[1]).put("name",f[2]).put("container_extension",f[3].isEmpty()?"ts":f[3]));}catch(JSONException ignored){}}
   for(String[] f:favs){String t=f[0],id=f[1],title=f[2],ext=f[3].isEmpty()?(t.equals("live")?"ts":"mp4"):f[3],k=f[4];String icon=t.equals("live")?"▣":t.equals("vod")?"▶":"▤";
    button("★ "+icon+"  "+title,list,()->{Runnable use=()->{if(!p.optString("id").equals(library.activeId())){switchPlaylist(p);mode="favorites";}};
     if(t.equals("series")){use.run();episodes(id,title);return;}
     new Dialogs.Builder(this).setTitle(title).setItems(new String[]{"Play","Remove Favorite"},(dialog,choice)->{if(choice==0){use.run();zapList=favLive;play(t,id,ext,title);}else{prefs.edit().remove(k).remove(pre+"ext_"+t+"_"+id).apply();favorites();}}).show();}).setTag(id);}}
  if(!focusResume(list)&&list.getChildCount()>1){for(int i=1;i<list.getChildCount();i++)if(list.getChildAt(i).isFocusable()){list.getChildAt(i).requestFocus();break;}}}
 static int favOrder(String type){return type.equals("live")?0:type.equals("vod")?1:2;}
 void episodes(String id,String title){episodesBack=null;Episodes.show(this,id,title);}
 String epgText(String value){try{return new String(android.util.Base64.decode(value,android.util.Base64.DEFAULT),java.nio.charset.StandardCharsets.UTF_8);}catch(IllegalArgumentException ex){return value;}}
 void guide(String id,String title){request("get_short_epg&stream_id="+enc(id)+"&limit=20",o->{JSONArray entries=o.optJSONArray("epg_listings");StringBuilder text=new StringBuilder();if(entries!=null)for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);if(e==null)continue;text.append(e.optString("start")).append(" – ").append(e.optString("end")).append("\n").append(epgText(e.optString("title"))).append("\n").append(epgText(e.optString("description"))).append("\n\n");}new Dialogs.Builder(this).setTitle(title+" • Program guide").setMessage(text.length()==0?"No guide data available from this provider.":text.toString()).setPositiveButton("Close",null).show();},"Unable to load guide");}
 void play(String type,String id,String ext,String title){MiniPlayer.close(this);/* a new channel or movie replaces the mini player */LivePreview.release();if(library.activeIsM3u()&&!library.m3uReady()){JSONArray keep=zapList;apiQuiet("get_live_categories",o->{if(o==null){Menus.alert(this,"Couldn't load this playlist. Refresh it from Playlists.");return;}zapList=keep;play(type,id,ext,title);});return;}library.recordPlay(type,id,ext,title);if(ExternalPlayer.open(this,type,streamUrl(type,id,ext),title)){zapList=null;pendingWatch=null;return;}watching=type.equals("series")&&pendingWatch!=null&&pendingWatch[1].equals(id)?pendingWatch:null;pendingWatch=null;String previousMode=mode;Runnable returnScreen=playerReturn;String cat=category;playerReturn=previousMode.equals("episodes")||previousMode.equals("guide")||previousMode.equals("details")?returnScreen:previousMode.equals("favorites")?()->favorites():previousMode.equals("search")?()->searchLive():previousMode.equals("msearch")?()->MasterSearch.show(this):previousMode.equals("recent")?()->recent():previousMode.equals("home")||previousMode.equals("setup")?()->home():()->{resumeCategory=cat;browse(previousMode);};String url=streamUrl(type,id,ext);screenGeneration++;mode="player";if(recovery!=null){recovery.stop();recovery=null;}if(player!=null)player.release();player=Players.create(this,prefs);final boolean hdhr=library.activeIsHdhr();if(hdhr)Players.explainTunerProblems(this,player);recovery=Recovery.attach(this,player,type.equals("live"),e->Toast.makeText(this,hdhr?Players.tunerMessage(e):type.equals("live")?"This channel stopped and couldn't reconnect. Try it again, or another channel. Settings > Live stream format or Buffer may help.":"Lost the connection to the server. Press play to try again.",Toast.LENGTH_LONG).show());subs=Subtitles.attach(this,player,type.equals("live"));PlayerView view=new PlayerView(this);view.setPlayer(player);view.setUseController(true);setContentView(remote.playerScreen(view,type,id,ext,title,zapList));zapList=null;player.setMediaItem(MediaItem.fromUri(url));player.prepare();if(watching!=null){long at=Watch.resumeAt(Watch.load(this,watching[0]),id);if(at>0){player.seekTo(at);Toast.makeText(this,"Resuming at "+Watch.clock(at),Toast.LENGTH_SHORT).show();}}player.play();view.requestFocus();}
 void closePlayer(){if(recovery!=null){recovery.stop();recovery=null;}if(player!=null){saveWatch();watching=null;remote.onPlayerExit();player.release();player=null;subs=null;}}
 /** Back on the last screen, or Exit in the side menu or on Home: ask before leaving WygTV. */
 void confirmExit(){
    new Dialogs.Builder(this).setTitle("Quit "+Brand.NAME+"?")
        .setMessage(MiniPlayer.active() || player != null ? "The player will also stop." : null)
        .setPositiveButton("Quit", (d, w) -> {
            if (MiniPlayer.active()) MiniPlayer.close(this);
            closePlayer();
            finish();
        })
        .setNegativeButton("Cancel", null).show();
}
 @Override public void onBackPressed(){if(remote.onBack())return;if(player!=null){closePlayer();if(playerReturn!=null)playerReturn.run();else if(liveOnly())home();else browse("live");return;}if(mode.equals("home")&&NavRail.openFromScreen(this))return;if(mode.equals("home")||mode.equals("setup")){confirmExit();return;}if(mode.equals("login")){leaveForm();return;}if(mode.equals("hdhr")){if(library.isEmpty()){if(Brand.OTA)finish();else setup();}else Menus.backToTuners(this);return;}if(mode.equals("manage")&&Manage.back(this))return;if(mode.equals("settings")&&Menus.settingsBack(this))return;if(mode.equals("playlists")&&Menus.playlistsBack(this))return;if(mode.equals("details")&&detailsBack!=null){detailsBack.run();return;}if(mode.equals("episodes")){Episodes.back(this);return;}if(mode.equals("guide")&&liveOnly()){if(!NavRail.openFromScreen(this))confirmExit();return;}if(mode.equals("search")||mode.equals("guide")||mode.equals("favorites")){browse("live");return;}if((mode.equals("live")||mode.equals("vod")||mode.equals("series"))&&LiveMenu.backToMenu(this))return;if(mode.equals("live")&&LiveMenu.back(this))return;/* Out of a screen's own menus: open the main menu on the left, not Home (Home only when picked there). */if(!liveOnly()&&NavRail.open(this))return;home();}
 @Override protected void onStop(){if(Pip.onStop(this)){super.onStop();return;}/* picture-in-picture window closed */MiniPlayer.onStop(this);if(player!=null){saveWatch();player.pause();}if(tvGuide!=null)tvGuide.pausePreview();LivePreview.release();super.onStop();}
 @Override protected void onStart(){super.onStart();Updater.onReturn(this);if(tvGuide!=null&&mode.equals("guide"))tvGuide.resumePreview();if(mode.equals("live")&&player==null)LivePreview.resume(this);}
 /** Every screen goes through here: while the mini player is on, its window is laid over the screen. */@Override public void setContentView(View v){if(MiniPlayer.active()&&!"player".equals(mode))v=MiniPlayer.wrap(this,v);super.setContentView(v);}@Override protected void onUserLeaveHint(){super.onUserLeaveHint();Pip.onUserLeaveHint(this);}@Override public void onPictureInPictureModeChanged(boolean in,android.content.res.Configuration c){if(Build.VERSION.SDK_INT>=26)super.onPictureInPictureModeChanged(in,c);Pip.changed(this,in);}@Override protected void onDestroy(){MiniPlayer.onDestroy();if(recovery!=null){recovery.stop();recovery=null;}if(player!=null){player.release();player=null;}super.onDestroy();}
